const uuid=/^[a-f\d-]{36}$/i,limit=32*1024*1024;
let dialogInProgress=false;
export function libraryURL(id){return '/library'+(uuid.test(id||'')?'?asset='+encodeURIComponent(id):'');}
export function applyURL(id,side='A'){if(!uuid.test(id||'')||!['A','B','pair'].includes(side))throw Error('请选择有效的图库素材');return '/workspace?asset='+encodeURIComponent(id)+'&side='+side+'#results';}
export async function libraryRequest(path='',data){let response;try{response=await fetch('/api/library/assets'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});}catch{throw Error('暂时无法连接图库，请先检查保存记录。');}let value;try{value=await response.json();}catch{throw Error('图库暂时没有返回可读取的结果，请刷新检查。');}if(!response.ok){const error=Error(typeof value.error==='string'?value.error:'图库请求失败（HTTP '+response.status+'）');error.status=response.status;throw error;}return value;}
export async function normalizeLibraryImage(input){
  let blob=input;if(typeof input==='string'&&/^data:image\/png;base64,[a-z\d+/]+=*$/i.test(input)){const raw=atob(input.slice(input.indexOf(',')+1));if(raw.length>limit)throw Error('每张 PNG 请控制在 32 MB 以内');blob=new Blob([Uint8Array.from(raw,char=>char.charCodeAt(0))],{type:'image/png'});}
  if(!(blob instanceof Blob)||!['image/png','image/jpeg','image/webp'].includes(blob.type))throw Error('请选择 PNG、JPG 或 WebP 图片');if(blob.size>limit)throw Error('单张图片不能超过 32 MB');
  let bitmap;try{bitmap=await createImageBitmap(blob);}catch{throw Error('图片无法读取，请选择有效的 PNG、JPG 或 WebP');}
  const width=bitmap.width,height=bitmap.height;try{if(!width||!height||width>16000||height>16000||width*height>64e6)throw Error('图片请控制在 16000 像素边长及 6400 万像素以内');if(blob.type==='image/png'){const signature=new Uint8Array(await blob.slice(0,8).arrayBuffer());if([137,80,78,71,13,10,26,10].some((value,i)=>signature[i]!==value))throw Error('PNG 文件内容无效');return {blob,width,height};}const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(bitmap,0,0);const png=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(Error('无法转换 PNG，请换一张图片')),'image/png'));if(png.size>limit)throw Error('转为 PNG 后超过 32 MB，请先减少图片文件大小');return {blob:png,width,height};}finally{bitmap.close();}
}
export function libraryImageData(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(blob);});}
function notify(){try{localStorage.setItem('zhijing-library-updated-v1',String(Date.now()));}catch{}window.dispatchEvent(new Event('zhijing-library-updated'));}
export function notifyLibraryChanged(){notify();}
function addDialogStyle(){if(document.getElementById('libraryDialogStyle'))return;const style=document.createElement('style');style.id='libraryDialogStyle';style.textContent='.lib-save-dialog{width:min(640px,calc(100vw - 28px));max-height:90dvh;overflow:auto;border:1px solid #dce3d5;border-radius:18px;padding:27px;background:#fbfbf6;color:#36523d;font:13px "Microsoft YaHei",sans-serif}.lib-save-dialog::backdrop{background:#20372e77;backdrop-filter:blur(5px)}.lib-save-dialog [hidden]{display:none!important}.lib-save-dialog h2{font:22px SimSun,serif;margin:0 0 10px}.lib-save-dialog p{font:11px/1.9 "Microsoft YaHei",sans-serif;color:#8b9a7d;margin:0 0 15px}.lib-save-dialog .lib-save-preview{display:flex;gap:10px;background:#f0f3e9;padding:12px;border-radius:9px;margin:16px 0}.lib-save-dialog img{object-fit:contain;max-height:170px;width:100%;min-width:0}.lib-save-dialog label{display:block;margin:12px 0 0;font:12px "Microsoft YaHei",sans-serif;color:#658056}.lib-save-dialog input,.lib-save-dialog textarea,.lib-save-dialog select{display:block;width:100%;min-width:0;border:1px solid #d9e2cf;border-radius:7px;padding:10px;background:white;color:#405a36;font:12px/1.6 "Microsoft YaHei",sans-serif;margin-top:7px;box-sizing:border-box}.lib-save-dialog textarea{min-height:72px;resize:vertical}.lib-save-dialog .lib-save-row{display:grid;grid-template-columns:1fr 1fr;gap:13px}.lib-save-dialog .lib-save-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:18px}.lib-save-dialog button{border:1px solid #d6e0ca;border-radius:7px;padding:10px 16px;background:#fff;color:#81966d;font:12px "Microsoft YaHei",sans-serif;cursor:pointer}.lib-save-dialog button[data-save]{background:#2e5741;color:white;border-color:#2e5741}.lib-save-dialog button:disabled{opacity:.45;cursor:default}.lib-save-dialog .lib-save-note{margin-top:12px}.lib-save-dialog .lib-save-feedback{margin:13px 0 0;min-height:18px;color:#a17752;overflow-wrap:anywhere}.lib-save-dialog .lib-save-second{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:15px}.lib-save-dialog .lib-save-second>span{font-size:11px;color:#8b9b7d;flex:1}.lib-save-dialog .lib-save-metric{font-size:10px;color:#9eaa91;margin-top:6px}@media(max-width:520px){.lib-save-dialog{padding:22px}.lib-save-dialog .lib-save-row{gap:10px}.lib-save-dialog [hidden]{display:none!important}.lib-save-dialog h2{font-size:20px}}';document.head.append(style);}
export async function saveAssetDialog({blob,name='我的花稿',print,source='',kind='pattern',imageB,recipe}={}){
  if(dialogInProgress||document.querySelector('.lib-save-dialog[open]'))throw Error('请先完成当前的图库保存');dialogInProgress=true;try{const primary=await normalizeLibraryImage(blob);let second=imageB?await normalizeLibraryImage(imageB):null;addDialogStyle();const dialog=document.createElement('dialog');dialog.className='lib-save-dialog';dialog.setAttribute('aria-label','保存到图库');dialog.innerHTML='<form><h2>保存到我的图库</h2><p>保留当前像素尺寸，保存后可选作 A 面、B 面或商品组合。此操作不调用 AI。</p><div class="lib-save-preview"><img data-primary alt="待保存的 A 面 / 主图"><img data-secondary alt="待保存的 B 面" hidden></div><p class="lib-save-metric"></p><label>名称<input name="name" maxlength="80" required></label><div class="lib-save-row"><label>分类<select name="kind"><option value="pattern">花型 / 花稿</option><option value="product">商品 / 成品图</option></select></label><label>款号<input name="code" maxlength="80" placeholder="选填"></label></div><div class="lib-save-row"><label>系列<input name="collection" maxlength="80" placeholder="例如：春日花园"></label><label>标签<input name="tags" maxlength="800" placeholder="用逗号分开，选填"></label></div><label>备注<textarea name="description" maxlength="2000" placeholder="记录风格、用途或需要保留的细节"></textarea></label><div class="lib-save-second" hidden><button type="button" data-b-choose>＋ 添加 B 面图片</button><span>商品可同时保存 A / B 面。</span><button type="button" data-b-remove hidden>移除 B 面</button><input type="file" data-b-file accept="image/png,image/jpeg,image/webp" hidden></div><p class="lib-save-note">PNG 原文件直接保存；JPG / WebP 本机转 PNG，不缩小像素尺寸。每面不超过 32 MB。</p><p class="lib-save-feedback" role="status" aria-live="polite"></p><div class="lib-save-actions"><button type="button" data-cancel>取消</button><button data-save type="submit">确认保存</button></div></form>';
  const form=dialog.querySelector('form'),field=key=>form.elements.namedItem(key),feedback=dialog.querySelector('.lib-save-feedback'),requestId=crypto.randomUUID(),urls=[];let saving=false,loadingB=false,finished=false;
  function preview(){const main=dialog.querySelector('[data-primary]'),back=dialog.querySelector('[data-secondary]');if(!main.src){main.src=URL.createObjectURL(primary.blob);urls.push(main.src);}back.hidden=!second;if(second){back.src=URL.createObjectURL(second.blob);urls.push(back.src);}dialog.querySelector('.lib-save-metric').textContent='A / 主图 '+primary.width+' × '+primary.height+' px'+(second?' · B 面 '+second.width+' × '+second.height+' px':'')+(print?.dpi?' · '+print.dpi+' DPI':'');dialog.querySelector('.lib-save-second').hidden=field('kind').value!=='product';dialog.querySelector('[data-b-remove]').hidden=!second;}
  field('name').value=String(name||'我的花稿').slice(0,80);field('kind').value=second||recipe?'product':kind==='product'?'product':'pattern';field('kind').disabled=!!recipe;field('kind').onchange=()=>{if(field('kind').value!=='product')second=null;preview();};preview();document.body.append(dialog);dialog.showModal();
  return await new Promise(resolve=>{
    function close(value){if(finished)return;finished=true;dialog.close();dialog.remove();urls.forEach(url=>URL.revokeObjectURL(url));resolve(value);}
    function controls(){form.querySelectorAll('button,input,select,textarea').forEach(control=>control.disabled=saving||loadingB);field('kind').disabled=saving||loadingB||!!recipe;dialog.querySelector('[data-save]').textContent=saving?'正在保存…':'确认保存';}
    dialog.querySelector('[data-cancel]').onclick=()=>{if(!saving&&!loadingB)close(null);};dialog.addEventListener('cancel',event=>{event.preventDefault();if(!saving&&!loadingB)close(null);});
    dialog.querySelector('[data-b-choose]').onclick=()=>dialog.querySelector('[data-b-file]').click();dialog.querySelector('[data-b-remove]').onclick=()=>{second=null;preview();};dialog.querySelector('[data-b-file]').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;loadingB=true;controls();try{second=await normalizeLibraryImage(file);preview();feedback.textContent='B 面已准备好，确认保存后才会入库。';}catch(error){feedback.textContent=error.message;}finally{loadingB=false;controls();}};
    form.onsubmit=async event=>{event.preventDefault();if(saving||loadingB)return;saving=true;controls();feedback.textContent='正在保存原尺寸图片…';try{const tags=field('tags').value.split(/[,，、]/).map(value=>value.trim()).filter(Boolean);if(tags.length>20||tags.some(value=>value.length>40))throw Error('标签最多 20 项，每项不超过 40 字。');const data={requestId,name:field('name').value.trim(),kind:field('kind').value,code:field('code').value.trim(),collection:field('collection').value.trim(),tags,description:field('description').value.trim(),source:String(source||'').slice(0,240),...(print?{print}:{}),...(field('kind').value==='product'&&recipe?{recipe}:{}),image:await libraryImageData(primary.blob),...(second?{imageB:await libraryImageData(second.blob)}:{})};const result=await libraryRequest('',data);if(!result.asset||!uuid.test(result.asset.id))throw Error('保存结果尚未确认，请在图库检查。');notify();close(result.asset);}catch(error){feedback.textContent=error.message+' 可重试保存核对，本次保存编号会保持不变。';}finally{saving=false;if(!finished)controls();}};
  });
  }finally{dialogInProgress=false;}
}
